#!/usr/bin/env bash
# Forever Addon Installer for Linux: pick which shelf addons to install or update in WoW Forever
# running under Wine, Lutris, Bottles, Heroic or Steam (Proton).
#
#   bash <(curl -fsSL __INSTALLER_SH_URL__)
#
# Generated by addon-hub/build.ps1 from installer.template.sh; edit the template, not the copy in dist/.
# The addon list comes from shelf.tsv on GitHub at run time (the copy embedded below is the offline fallback),
# and each addon's latest version from its GitHub releases.
#
# Options:  install-forever-addons.sh [--select all|Name,Name] [--text] [WoW folder]
# Env:      FOREVER_WOW=<folder>  FOREVER_SELECT=all|Name,Name  FOREVER_UI=zenity|kdialog|whiptail|text
set -u

SHELF_URL='__SHELF_URL__'
SHELF_PAGE='__SHELF_PAGE__'
INSTALLER_SH_URL='__INSTALLER_SH_URL__'
FALLBACK_B64='__SHELF_B64__'
FLAVOR='_forever_'
CONFIG_DIR="${XDG_CONFIG_HOME:-$HOME/.config}/forever-addons"
SAVED_PATH="$CONFIG_DIR/wow-path"
UA='ForeverAddonInstaller'
TITLE='Forever Addon Installer'

# ---------------------------------------------------------------- output

if [ -t 1 ]; then
  B=$'\e[1m'; DIM=$'\e[2m'; RED=$'\e[31m'; GRN=$'\e[32m'; YEL=$'\e[33m'; CYN=$'\e[36m'; RST=$'\e[0m'
else
  B=''; DIM=''; RED=''; GRN=''; YEL=''; CYN=''; RST=''
fi
say()  { printf '%s\n' "$*"; }
good() { printf '%s\n' "${GRN}$*${RST}"; }
warn() { printf '%s\n' "${YEL}$*${RST}" >&2; }
bad()  { printf '%s\n' "${RED}$*${RST}" >&2; }

# Keyboard input: the terminal when there is one (so `curl ... | bash` still works), else stdin.
if { exec 3</dev/tty; } 2>/dev/null; then :; else exec 3<&0; fi
ask() { local reply=''; printf '%s' "$1" >&2; IFS= read -r reply <&3 || true; printf '%s' "$reply"; }

# ---------------------------------------------------------------- arguments

ARG_WOW=''; SELECT="${FOREVER_SELECT:-}"; UI="${FOREVER_UI:-}"
while [ $# -gt 0 ]; do
  case "$1" in
    -h|--help) sed -n '2,13p' "$0" 2>/dev/null | sed 's/^# \{0,1\}//'; exit 0 ;;
    --select) SELECT="${2:-}"; shift ;;
    --select=*) SELECT="${1#*=}" ;;
    --text) UI='text' ;;
    *) ARG_WOW="$1" ;;
  esac
  shift
done
[ -n "${FOREVER_WOW:-}" ] && ARG_WOW="$FOREVER_WOW"

if [ -z "$UI" ]; then
  if [ -n "$SELECT" ]; then UI='none'
  elif [ -n "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ] && command -v zenity >/dev/null 2>&1; then UI='zenity'
  elif [ -n "${DISPLAY:-}${WAYLAND_DISPLAY:-}" ] && command -v kdialog >/dev/null 2>&1; then UI='kdialog'
  elif command -v whiptail >/dev/null 2>&1 && [ -t 1 ]; then UI='whiptail'
  elif command -v dialog >/dev/null 2>&1 && [ -t 1 ]; then UI='dialog'
  else UI='text'
  fi
fi
GUI=0; case "$UI" in zenity|kdialog) GUI=1 ;; esac

# A message the person will see whether this runs in a terminal or was double-clicked.
notice() { # kind(info|warning|error) text
  local kind="$1" text="$2"
  case "$UI" in
    zenity) zenity --"$kind" --title="$TITLE" --width=420 --no-wrap --text="$text" 2>/dev/null ;;
    kdialog) case "$kind" in error) kdialog --title "$TITLE" --error "$text" ;; warning) kdialog --title "$TITLE" --sorry "$text" ;; *) kdialog --title "$TITLE" --msgbox "$text" ;; esac 2>/dev/null ;;
    *) case "$kind" in error) bad "$text" ;; warning) warn "$text" ;; *) say "$text" ;; esac ;;
  esac
}
die() { notice error "$1"; exit 1; }

# ---------------------------------------------------------------- tools

if command -v curl >/dev/null 2>&1; then
  fetch()    { curl -fsSL --max-time 60 -A "$UA" "$1"; }
  fetch_to() { curl -fsSL --max-time 120 -A "$UA" -o "$2" "$1"; }
  redirect() { curl -sS --max-time 15 -A "$UA" -o /dev/null -w '%{redirect_url}' "$1"; }
elif command -v wget >/dev/null 2>&1; then
  fetch()    { wget -q -T 60 -U "$UA" -O - "$1"; }
  fetch_to() { wget -q -T 120 -U "$UA" -O "$2" "$1"; }
  redirect() { wget -S --spider -T 15 -U "$UA" --max-redirect=0 "$1" 2>&1 | sed -n 's/^ *[Ll]ocation: *//p' | tr -d '\r' | head -n 1; }
else
  die "This installer needs curl or wget. Install one (for example: sudo apt install curl) and run it again."
fi

if command -v unzip >/dev/null 2>&1; then unzip_to() { unzip -q -o "$1" -d "$2"; }
elif command -v bsdtar >/dev/null 2>&1; then unzip_to() { mkdir -p "$2" && bsdtar -xf "$1" -C "$2"; }
elif command -v python3 >/dev/null 2>&1; then unzip_to() { python3 -c 'import sys, zipfile; zipfile.ZipFile(sys.argv[1]).extractall(sys.argv[2])' "$1" "$2"; }
elif command -v busybox >/dev/null 2>&1; then unzip_to() { mkdir -p "$2" && busybox unzip -q -o "$1" -d "$2"; }
else
  die "This installer needs unzip (or bsdtar or python3) to unpack addons. Install unzip (for example: sudo apt install unzip) and run it again."
fi

b64d() { base64 -d 2>/dev/null || openssl base64 -d -A 2>/dev/null || python3 -c 'import sys, base64; sys.stdout.buffer.write(base64.b64decode(sys.stdin.read()))'; }

# ---------------------------------------------------------------- finding WoW Forever

is_forever() { [ -n "$1" ] && [ -d "$1" ] && [ "$(basename "$1")" = "$FLAVOR" ]; }

# Accepts the World of Warcraft folder, the _forever_ folder, or a folder inside it.
resolve_pick() {
  local p="${1%/}"
  [ -z "$p" ] && return 1
  case "$p" in "~"*) p="$HOME${p#\~}" ;; esac
  while [ -n "$p" ] && [ "$p" != "/" ] && [ "$p" != "." ]; do
    if is_forever "$p"; then printf '%s\n' "$p"; return 0; fi
    if is_forever "$p/$FLAVOR"; then printf '%s\n' "$p/$FLAVOR"; return 0; fi
    p="$(dirname "$p")"
  done
  return 1
}

# Every WoW Forever folder in the usual Wine, Lutris, Bottles, Heroic and Steam places.
find_all_forever() {
  local -a prefixes=() found=()
  local d p w
  shopt -s nullglob
  prefixes+=("$HOME/.wine" "$HOME"/.local/share/wineprefixes/* "$HOME"/.PlayOnLinux/wineprefix/*)
  prefixes+=("$HOME"/Games/* "$HOME"/Games/*/* "$HOME"/.local/share/lutris/prefixes/*)
  prefixes+=("$HOME"/.local/share/bottles/bottles/* "$HOME"/.var/app/com.usebottles.bottles/data/bottles/bottles/*)
  prefixes+=("$HOME"/Games/Heroic/Prefixes/* "$HOME"/Games/Heroic/Prefixes/default/* "$HOME"/.config/heroic/Prefixes/*)
  for d in "$HOME/.steam/steam" "$HOME/.local/share/Steam" "$HOME/.var/app/com.valvesoftware.Steam/.local/share/Steam"; do
    prefixes+=("$d"/steamapps/compatdata/*/pfx)
  done
  for p in "${prefixes[@]}"; do
    for w in "$p"/drive_c/{"Program Files (x86)","Program Files",Games,Blizzard}/"World of Warcraft" "$p"/{drive_c,drive_c/users/*/Games}/"World of Warcraft" "$p/World of Warcraft"; do
      is_forever "$w/$FLAVOR" && found+=("$w/$FLAVOR")
    done
  done
  # Windows drives mounted for dual boot, and anything else: a bounded search.
  if [ ${#found[@]} -eq 0 ]; then
    local -a roots=()
    for d in "$HOME" /mnt /media /run/media; do [ -d "$d" ] && roots+=("$d"); done
    local t=''; command -v timeout >/dev/null 2>&1 && t='timeout 25'
    while IFS= read -r w; do found+=("$w"); done < <($t find "${roots[@]}" -maxdepth 9 -type d -name "$FLAVOR" -path "*World of Warcraft/$FLAVOR" 2>/dev/null)
  fi
  shopt -u nullglob
  [ ${#found[@]} -gt 0 ] && printf '%s\n' "${found[@]}" | awk '!seen[$0]++'
}

pick_folder_dialog() {
  case "$UI" in
    zenity) zenity --file-selection --directory --title="Pick your World of Warcraft folder (the one with $FLAVOR inside)" 2>/dev/null ;;
    kdialog) kdialog --title "Pick your World of Warcraft folder (the one with $FLAVOR inside)" --getexistingdirectory "$HOME" 2>/dev/null ;;
    *) ask "Drag your World of Warcraft folder here, or type its path: " ;;
  esac
}

choose_one() { # prompt, then options on stdin; prints the chosen one
  local prompt="$1" i n reply; local -a opts=()
  while IFS= read -r i; do opts+=("$i"); done
  n=${#opts[@]}
  [ "$n" -eq 1 ] && { printf '%s\n' "${opts[0]}"; return 0; }
  case "$UI" in
    zenity)
      local -a rows=(); for i in "${opts[@]}"; do rows+=(FALSE "$i"); done; rows[0]=TRUE
      zenity --list --radiolist --title="$TITLE" --text="$prompt" --column=' ' --column='Folder' --width=720 --height=320 "${rows[@]}" 2>/dev/null ;;
    kdialog)
      local -a rows=(); local k=0; for i in "${opts[@]}"; do rows+=("$i" "$i" "$([ $k -eq 0 ] && echo on || echo off)"); k=$((k+1)); done
      kdialog --title "$TITLE" --radiolist "$prompt" "${rows[@]}" 2>/dev/null ;;
    *)
      say "$prompt" >&2
      for i in "${!opts[@]}"; do printf '  %d) %s\n' $((i+1)) "${opts[$i]}" >&2; done
      reply="$(ask "Which one? [1]: ")"; reply="${reply:-1}"
      if [[ "$reply" =~ ^[0-9]+$ ]] && [ "$reply" -ge 1 ] && [ "$reply" -le "$n" ]; then printf '%s\n' "${opts[$((reply-1))]}"; else return 1; fi ;;
  esac
}

find_forever() {
  local p
  if [ -n "$ARG_WOW" ]; then
    resolve_pick "$ARG_WOW" && return 0
    warn "There's no $FLAVOR folder in $ARG_WOW."
  fi
  if [ -f "$SAVED_PATH" ]; then
    p="$(head -n 1 "$SAVED_PATH")"
    is_forever "$p" && { printf '%s\n' "$p"; return 0; }
  fi
  [ "$GUI" -eq 0 ] && say "${DIM}Looking for WoW Forever...${RST}" >&2
  local all; all="$(find_all_forever)"
  if [ -n "$all" ]; then
    printf '%s\n' "$all" | choose_one "Found WoW Forever in more than one place. Which one should get the addons?" && return 0
  fi
  [ -n "$SELECT" ] && return 1
  notice warning "Couldn't find WoW Forever by itself. Pick your World of Warcraft folder next (the one with $FLAVOR inside it)." >&2
  for _ in 1 2 3; do
    p="$(pick_folder_dialog)" || return 1
    [ -z "$p" ] && return 1
    p="${p%\'}"; p="${p#\'}"; p="${p%\"}"; p="${p#\"}"; p="${p%"${p##*[![:space:]]}"}"
    resolve_pick "$p" && return 0
    notice warning "That folder has no $FLAVOR folder in it. Pick the World of Warcraft folder WoW Forever is installed in." >&2
  done
  return 1
}

# Wine folders can be any case on Linux: reuse Interface/AddOns as it is already spelled.
ci_child() { # parent name
  local c
  for c in "$1"/*; do [ -d "$c" ] && [ "$(basename "$c" | tr '[:upper:]' '[:lower:]')" = "$(printf '%s' "$2" | tr '[:upper:]' '[:lower:]')" ] && { printf '%s\n' "$c"; return; }; done
  printf '%s\n' "$1/$2"
}
addons_dir() { ci_child "$(ci_child "$WOW" Interface)" AddOns; }

# ---------------------------------------------------------------- the shelf and versions

NAMES=(); TITLES=(); REPOS=(); NOTES=(); TAGS=(); LATEST=(); HAVE=(); STATUS=(); WANT=()

read_shelf() {
  local name title repo notes
  NAMES=(); TITLES=(); REPOS=(); NOTES=()
  while IFS=$'\t' read -r name title repo notes || [ -n "$name" ]; do
    name="${name%$'\r'}"; notes="${notes%$'\r'}"
    case "$name" in ''|'#'*) continue ;; esac
    [ -z "$repo" ] && continue
    NAMES+=("$name"); TITLES+=("${title:-$name}"); REPOS+=("$repo"); NOTES+=("$notes")
  done
}

load_shelf() {
  local text
  text="$(fetch "$SHELF_URL" 2>/dev/null)" && read_shelf <<< "$text"
  if [ ${#NAMES[@]} -eq 0 ]; then
    read_shelf < <(printf '%s' "$FALLBACK_B64" | b64d)
  fi
  [ ${#NAMES[@]} -gt 0 ]
}

latest_tag() { # repo -> tag, from where /releases/latest redirects (no API rate limit)
  local loc; loc="$(redirect "https://github.com/$1/releases/latest" 2>/dev/null)" || return 1
  case "$loc" in */releases/tag/*) printf '%s\n' "${loc##*/releases/tag/}" ;; *) return 1 ;; esac
}

installed_version() { # name
  local toc; toc="$(addons_dir)/$1/$1.toc"
  [ -f "$toc" ] || return 1
  local v; v="$(sed -n 's/^##[[:space:]]*Version:[[:space:]]*//p' "$toc" | head -n 1 | tr -d '\r')"
  printf '%s\n' "${v:-?}"
}

version_lt() { [ "$1" != "$2" ] && [ "$(printf '%s\n%s\n' "$1" "$2" | sort -V | head -n 1)" = "$1" ]; }

refresh_status() {
  local i
  for i in "${!NAMES[@]}"; do
    HAVE[$i]="$(installed_version "${NAMES[$i]}" || true)"
    if [ -z "${LATEST[$i]:-}" ]; then STATUS[$i]='Unavailable'
    elif [ -z "${HAVE[$i]}" ]; then STATUS[$i]='Not installed'
    elif version_lt "${HAVE[$i]}" "${LATEST[$i]}"; then STATUS[$i]='Update available'
    else STATUS[$i]='Up to date'
    fi
  done
}

check_versions() {
  local i tag
  for i in "${!NAMES[@]}"; do
    tag="$(latest_tag "${REPOS[$i]}" || true)"
    TAGS[$i]="$tag"; LATEST[$i]="${tag#v}"
  done
  refresh_status
}

# Downloads the release zip and replaces the addon's folder(s). Saved settings live in WTF/, so they're kept.
install_addon() { # index tmpdir
  local i="$1" tmp="$2" dest d
  dest="$(addons_dir)"
  mkdir -p "$dest" || return 1
  local zip="$tmp/${NAMES[$i]}.zip" out="$tmp/${NAMES[$i]}"
  fetch_to "https://github.com/${REPOS[$i]}/releases/download/${TAGS[$i]}/${NAMES[$i]}-${LATEST[$i]}.zip" "$zip" || { ERR="the download failed"; return 1; }
  unzip_to "$zip" "$out" >/dev/null 2>&1 || { ERR="the download wasn't a valid zip"; return 1; }
  local any=0
  for d in "$out"/*/; do
    d="${d%/}"; [ -d "$d" ] || continue
    any=1
    rm -rf "${dest:?}/$(basename "$d")"
    cp -R "$d" "$dest/" || { ERR="couldn't copy into $dest"; return 1; }
  done
  [ "$any" -eq 1 ] || { ERR="the download has no addon folder in it"; return 1; }
}

wow_running() { pgrep -fi 'wow(classic|-64)?\.exe' >/dev/null 2>&1; }

# ---------------------------------------------------------------- picking addons

suggest_defaults() {
  local i any=0
  for i in "${!NAMES[@]}"; do [ -n "${HAVE[$i]}" ] && any=1; done
  for i in "${!NAMES[@]}"; do
    WANT[$i]=0
    [ -z "${LATEST[$i]}" ] && continue
    if [ "$any" -eq 0 ] || [ "${STATUS[$i]}" = 'Update available' ]; then WANT[$i]=1; fi
  done
}

apply_select() { # comma list or "all"
  local i w
  for i in "${!NAMES[@]}"; do
    WANT[$i]=0
    IFS=',' read -ra picks <<< "$1"
    for w in "${picks[@]}"; do
      w="$(printf '%s' "$w" | tr -d '[:space:]')"
      if [ "$w" = 'all' ] || [ "$w" = "${NAMES[$i]}" ]; then [ -n "${LATEST[$i]}" ] && WANT[$i]=1; fi
    done
  done
}

set_wanted_from_names() { # names on stdin, one per line
  local i n; for i in "${!NAMES[@]}"; do WANT[$i]=0; done
  while IFS= read -r n; do
    n="${n//\"/}"; [ -z "$n" ] && continue
    for i in "${!NAMES[@]}"; do [ "${NAMES[$i]}" = "$n" ] && [ -n "${LATEST[$i]}" ] && WANT[$i]=1; done
  done
}

shown() { [ -n "$1" ] && printf '%s' "$1" || printf '%s' '-'; }

pick_zenity() {
  local i rows=() out
  for i in "${!NAMES[@]}"; do
    rows+=("$([ "${WANT[$i]}" -eq 1 ] && echo TRUE || echo FALSE)" "${NAMES[$i]}" "${TITLES[$i]}" "${STATUS[$i]}" "$(shown "${HAVE[$i]}")" "$(shown "${LATEST[$i]}")" "${NOTES[$i]}")
  done
  out="$(zenity --list --checklist --title="$TITLE" --width=980 --height=420 \
    --text="<b>WoW Forever Addons</b>\nTick the addons you want. Ticked addons are installed or updated to the latest version; the rest are left alone.\n<small>Folder: $WOW</small>" \
    --ok-label='Install' --cancel-label='Close' --separator=$'\n' --print-column=2 --hide-column=2 \
    --column='Install' --column='id' --column='Addon' --column='Status' --column='You have' --column='Latest' --column='What it does' \
    "${rows[@]}" 2>/dev/null)" || return 1
  set_wanted_from_names <<< "$out"
}

pick_kdialog() {
  local i rows=() out
  for i in "${!NAMES[@]}"; do
    rows+=("${NAMES[$i]}" "${TITLES[$i]}  (${STATUS[$i]}$([ -n "${LATEST[$i]}" ] && printf ', latest %s' "${LATEST[$i]}"))" "$([ "${WANT[$i]}" -eq 1 ] && echo on || echo off)")
  done
  out="$(kdialog --title "$TITLE" --separate-output --checklist "Tick the addons you want. Ticked addons are installed or updated to the latest version; the rest are left alone." "${rows[@]}" 2>/dev/null)" || return 1
  set_wanted_from_names <<< "$out"
}

pick_whiptail() { # whiptail or dialog
  local i rows=() out h
  for i in "${!NAMES[@]}"; do
    rows+=("${NAMES[$i]}" "$(printf '%-18s %s' "${STATUS[$i]}" "${TITLES[$i]}")" "$([ "${WANT[$i]}" -eq 1 ] && echo ON || echo OFF)")
  done
  h=$(( ${#NAMES[@]} + 10 )); [ "$h" -gt 22 ] && h=22
  out="$("$UI" --title "$TITLE" --separate-output --checklist "Space ticks an addon, Enter installs the ticked ones.\nFolder: $WOW" "$h" 78 "${#NAMES[@]}" "${rows[@]}" <&3 4>&1 1>&2 2>&4)" || return 1
  set_wanted_from_names <<< "$out"
}

pick_text() {
  local i reply tok n=${#NAMES[@]} mark
  say ''
  say "  ${B}WoW Forever Addons${RST}   ${DIM}$WOW${RST}"
  say ''
  for i in "${!NAMES[@]}"; do
    mark=' '; [ "${WANT[$i]}" -eq 1 ] && mark='x'
    local col="$RST"
    case "${STATUS[$i]}" in 'Up to date') col="$GRN" ;; 'Update available') col="$YEL" ;; 'Unavailable') col="$DIM" ;; esac
    printf '  %2d [%s] %-22s %s%-16s%s %-8s -> %s\n' $((i+1)) "$mark" "${TITLES[$i]}" "$col" "${STATUS[$i]}" "$RST" "$(shown "${HAVE[$i]}")" "$(shown "${LATEST[$i]}")"
    [ -n "${NOTES[$i]}" ] && printf '            %s%s%s\n' "$DIM" "${NOTES[$i]}" "$RST"
  done
  say ''
  reply="$(ask "Numbers to install (e.g. 1 3), a = all, Enter = the ticked ones [x], q = quit: ")"
  case "$reply" in
    q|Q) return 1 ;;
    '') return 0 ;;
    a|A|all) apply_select all; return 0 ;;
  esac
  for i in "${!NAMES[@]}"; do WANT[$i]=0; done
  for tok in ${reply//,/ }; do
    if [[ "$tok" =~ ^[0-9]+$ ]] && [ "$tok" -ge 1 ] && [ "$tok" -le "$n" ]; then
      i=$((tok-1))
      if [ -n "${LATEST[$i]}" ]; then WANT[$i]=1; else warn "${TITLES[$i]} has no release to install yet; skipped."; fi
    else
      warn "Ignored '$tok' (not a number from the list)."
    fi
  done
}

# ---------------------------------------------------------------- app menu entry

MENU_FILE="${XDG_DATA_HOME:-$HOME/.local/share}/applications/forever-addons.desktop"
LOCAL_COPY="$CONFIG_DIR/install-forever-addons.sh"

offer_menu_entry() {
  [ -f "$MENU_FILE" ] || [ -f "$CONFIG_DIR/no-menu-entry" ] && return 0
  local yes=1
  case "$UI" in
    zenity) zenity --question --title="$TITLE" --width=380 --text='Add "WoW Forever Addons" to your app menu, so you can update with one click next time?' 2>/dev/null || yes=0 ;;
    kdialog) kdialog --title "$TITLE" --yesno 'Add "WoW Forever Addons" to your app menu, so you can update with one click next time?' 2>/dev/null || yes=0 ;;
    *) case "$(ask 'Add "WoW Forever Addons" to your app menu for one-click updates? [Y/n] ')" in n*|N*) yes=0 ;; esac ;;
  esac
  if [ "$yes" -eq 0 ]; then : > "$CONFIG_DIR/no-menu-entry"; return 0; fi
  fetch_to "$INSTALLER_SH_URL" "$LOCAL_COPY.new" 2>/dev/null && mv -f "$LOCAL_COPY.new" "$LOCAL_COPY" || { [ -f "$0" ] && cp -f "$0" "$LOCAL_COPY"; } 2>/dev/null
  [ -f "$LOCAL_COPY" ] || { warn "Couldn't save a copy of the installer, so no menu entry was made."; return 0; }
  chmod +x "$LOCAL_COPY"
  mkdir -p "$(dirname "$MENU_FILE")"
  local term=true; { command -v zenity >/dev/null 2>&1 || command -v kdialog >/dev/null 2>&1; } && term=false
  cat > "$MENU_FILE" <<EOF
[Desktop Entry]
Type=Application
Name=WoW Forever Addons
Comment=Install or update your WoW Forever addons
Exec=bash "$LOCAL_COPY"
Icon=system-software-update
Terminal=$term
Categories=Game;
EOF
  [ "$GUI" -eq 0 ] && good 'Added "WoW Forever Addons" to your app menu.'
}

# When run from the menu entry's copy, quietly fetch the newest installer for next time.
update_local_copy() {
  [ "$(cd "$(dirname "$0")" 2>/dev/null && pwd)/$(basename "$0")" = "$LOCAL_COPY" ] || return 0
  fetch_to "$INSTALLER_SH_URL" "$LOCAL_COPY.new" 2>/dev/null && head -n 1 "$LOCAL_COPY.new" | grep -q '^#!' && mv -f "$LOCAL_COPY.new" "$LOCAL_COPY"
  rm -f "$LOCAL_COPY.new"
}

# ---------------------------------------------------------------- main

[ "$GUI" -eq 0 ] && { say ''; say "${CYN}${B}$TITLE${RST}"; }

WOW="$(find_forever)" || die "Couldn't find WoW Forever. Run this again with your World of Warcraft folder, for example:
  bash install-forever-addons.sh \"\$HOME/Games/battlenet/drive_c/Program Files (x86)/World of Warcraft\""
[ -z "${FOREVER_WOW:-}" ] && mkdir -p "$CONFIG_DIR" && printf '%s\n' "$WOW" > "$SAVED_PATH"
[ "$GUI" -eq 0 ] && say "WoW Forever folder: $WOW"

if [ "$UI" = 'zenity' ]; then
  { load_shelf && check_versions; OK=$?; echo 100; } > >(zenity --progress --pulsate --auto-close --no-cancel --title="$TITLE" --text='Checking for the latest versions...' 2>/dev/null)
else
  [ "$GUI" -eq 0 ] && say "${DIM}Checking for the latest versions...${RST}"
  load_shelf && check_versions; OK=$?
fi
[ "$OK" -eq 0 ] || die "Couldn't load the addon list. Check your internet connection and try again."
update_local_copy

if [ -n "$SELECT" ]; then
  apply_select "$SELECT"
else
  suggest_defaults
  case "$UI" in
    zenity) pick_zenity ;;
    kdialog) pick_kdialog ;;
    whiptail|dialog) pick_whiptail ;;
    *) pick_text ;;
  esac || { [ "$GUI" -eq 0 ] && say 'Closed without changing anything.'; exit 0; }
fi

CHOSEN=(); for i in "${!NAMES[@]}"; do [ "${WANT[$i]:-0}" -eq 1 ] && CHOSEN+=("$i"); done
if [ ${#CHOSEN[@]} -eq 0 ]; then
  notice info 'Nothing was ticked, so nothing was changed.'
  exit 0
fi

TMP="$(mktemp -d "${TMPDIR:-/tmp}/forever-addons.XXXXXX")" || die "Couldn't make a temporary folder."
trap 'rm -rf "$TMP"' EXIT
RESULTS="$TMP/results"; : > "$RESULTS"

run_installs() {
  local k=0 i was note
  for i in "${CHOSEN[@]}"; do
    printf '# Installing %s %s...\n' "${TITLES[$i]}" "${LATEST[$i]}"
    [ "$GUI" -eq 0 ] && printf '  %s %s... ' "${TITLES[$i]}" "${LATEST[$i]}" >&2
    was="${HAVE[$i]}"; ERR=''
    if install_addon "$i" "$TMP"; then
      note=''; if [ -n "$was" ] && [ "$was" != "${LATEST[$i]}" ]; then note=" (was $was)"; elif [ -n "$was" ]; then note=' (reinstalled)'; fi
      printf 'ok\t%s %s%s\n' "${TITLES[$i]}" "${LATEST[$i]}" "$note" >> "$RESULTS"
      [ "$GUI" -eq 0 ] && printf '%s\n' "${GRN}installed${note}${RST}" >&2
    else
      printf 'fail\t%s: %s\n' "${TITLES[$i]}" "${ERR:-it didn't install}" >> "$RESULTS"
      [ "$GUI" -eq 0 ] && printf '%s\n' "${RED}failed: ${ERR:-it didn't install}${RST}" >&2
    fi
    k=$((k+1)); printf '%d\n' $(( k * 100 / ${#CHOSEN[@]} ))
  done
}

if [ "$UI" = 'zenity' ]; then
  run_installs | zenity --progress --auto-close --no-cancel --percentage=0 --title="$TITLE" --text='Installing...' 2>/dev/null
else
  run_installs > /dev/null
fi

OKS="$(sed -n 's/^ok\t//p' "$RESULTS")"
FAILS="$(sed -n 's/^fail\t//p' "$RESULTS")"
if [ -n "$FAILS" ]; then
  notice error "Some addons didn't install:
$FAILS
$([ -n "$OKS" ] && printf '\nInstalled:\n%s' "$OKS")

Check your internet connection and try again."
  exit 1
fi
TAIL='Start WoW and they will be in your AddOns list.'
wow_running && TAIL='WoW is running: type /reload in game to load them.'
if [ "$GUI" -eq 1 ]; then notice info "Done! Installed:
$OKS

$TAIL"
else good "Done! $TAIL"; fi
[ -z "$SELECT" ] && offer_menu_entry
exit 0
